const input=$json.body??$json;
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const leadId=input.lead_id, dealId=input.deal_id, propertyId=input.property_id;
const signatureStatus=String(input.signature_status??input.execution_status??"").toLowerCase();
const executedAt=String(input.executed_at??input.signature_executed_at??"").trim();
const contractPrice=Number(input.contract_price??input.accepted_price??input.offer_price);
const mao=Number(input.dynamic_mao??input.adjusted_mao??input.mao);
const closingDate=String(input.closing_date??"").trim();
const sellerReady=Boolean(input.seller_id||input.seller_name||input.seller_phone||input.seller_email);
const buyerReady=Boolean(input.buyer_id||input.buyer_name||input.buyer_email);
const executionReady=["signed","executed","completed"].includes(signatureStatus)||Boolean(input.executed_agreement||input.signature_executed===true);
const identityReady=Boolean(leadId&&dealId&&propertyId);
const priceProtected=Number.isFinite(contractPrice)&&Number.isFinite(mao)&&contractPrice>0&&mao>0&&contractPrice<=mao;
const closingDateReady=Boolean(closingDate);
let status="blocked",nextWorkflow="WF-126",human=true,reason="";
if(blockers.length){reason="active transaction blockers remain";}
else if(!identityReady){reason="lead/deal/property identity is incomplete";}
else if(!executionReady){reason="executed signature evidence is missing";}
else if(!executedAt&&!input.executed_agreement){reason="signature execution timestamp/evidence is incomplete";}
else if(!priceProtected){reason="contract price is invalid or exceeds protected dynamic MAO";}
else if(!sellerReady){reason="seller identity/evidence is incomplete";}
else if(!closingDateReady){reason="closing date is missing";}
else{status="transaction_ready";nextWorkflow="WF-304";human=true;reason="executed agreement validated and transaction is ready for closing coordination";}
const idempotencyKey=input.idempotency_key||`wf-303:${dealId||"unknown"}:${executedAt||input.signature_event_id||input.version||1}`;
return [{json:{...input,workflow:"WF-303",workflow_name:"Executed Signature → Transaction Readiness & Closing Launch Controller",status,transaction_readiness:{execution_ready:executionReady,identity_ready:identityReady,price_protected:priceProtected,seller_ready:sellerReady,buyer_ready:buyerReady,closing_date_ready:closingDateReady,contract_price:Number.isFinite(contractPrice)?contractPrice:null,dynamic_mao:Number.isFinite(mao)?mao:null,closing_date:closingDate||null,executed_at:executedAt||null},next_workflow:nextWorkflow,human_review_required:human,audit:{event_type:"transaction_readiness",idempotency_key:idempotencyKey,reason}}}];
